'use strict';
const DATA=JSON.parse(document.getElementById('lesson-data').textContent),KEY='honghao-simple-writing-v1';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let stored={};try{stored=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{}
const state={page:'home',view:'parts',pattern:'can',subject:0,choices:{can:0,should:0,lets:0},all:false,hideSentence:false,font:19,teacher:false,hideZh:false,voices:'',saved:[],exercises:{},drafts:['','','','',''],comment:'',...stored};
if(!Array.isArray(state.drafts)||state.drafts.length!==5)state.drafts=['','','','',''];
let voiceList=[],timer;const trial={};
const ptn=()=>DATA.patterns.find(p=>p.id===state.pattern)||DATA.patterns[0];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('记录暂时无法保存，可导出文字备份。')}}
function toast(t){$('#toast').textContent=t;clearTimeout(timer);timer=setTimeout(()=>$('#toast').textContent='',3500)}
function heading(k,t,d){return `<div class="eyebrow">TONIGHT · MODULE 01 / ${k}</div><h1>${t}</h1><p class="lead">${d}</p>`}
function sentence(text,label='听这句'){return `<button class="small" data-act="speak" data-text="${esc(text)}">▷ ${label}</button>`}
function model(p=ptn()){const b=p.bank[state.choices[p.id]]||p.bank[0];const sub=p.id==='can'?DATA.subjects[state.subject]||DATA.subjects[0]:[p.subject,p.subjectZh];return {en:p.id==='lets'?`${p.fixed} ${b.en}!`:`${sub[0]} ${p.fixed} ${b.en}.`,zh:p.id==='lets'?`让我们一起${b.zh}吧！`:p.id==='can'?`${sub[1]}能帮助我们${b.zh}。`:`我们应该${b.zh}。`}}
function recordFor(q){return state.exercises[q.id]||(state.exercises[q.id]={text:'',checked:false})}
function stop(){if('speechSynthesis'in window)speechSynthesis.cancel()}
function go(page){stop();state.page=page;if(['can','should','lets'].includes(page)){state.pattern=page;state.view='parts';state.all=false}save();render();window.scrollTo(0,0)}
function render(){document.documentElement.style.setProperty('--size',state.font+'px');document.body.classList.toggle('hide-zh',state.hideZh);$('#teacher').textContent=state.teacher?'教师参考：开':'学生模式';$('#teacher').setAttribute('aria-pressed',state.teacher);$('#hide-zh').textContent=state.hideZh?'显示中文':'遮住中文';
 $('#nav').innerHTML=[['home','今晚的任务','先看目标'],['can','① 阅读能帮助我们…','Reading can help us…'],['should','② 我们应该…','We should…'],['lets','③ 让我们一起…','Let’s…'],['write','④ 自己写五句话','从语块到小段落'],['saved','我的句子与记录','保存 · 导出']].map(([id,t,s])=>`<button data-act="page" data-id="${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${t}<small>${s}</small></button>`).join('');
 $('#content').innerHTML=(state.teacher?'<p class="teacher-note">教师参考已开启。独立练习时可切回学生模式，再按需展开答案。</p>':'')+(state.page==='home'?home():state.page==='write'?writeView():state.page==='saved'?savedView():patternView());
 $('#print-area').innerHTML=`<h1>简单句写作 · 我的学习单</h1><h2>我写的五句话</h2><div class="writing-sheet">${esc(state.drafts.filter(Boolean).join('\n'))||'尚未填写'}</div><h2>我保存的句子</h2><ol>${state.saved.map(s=>`<li>${esc(s.en)}</li>`).join('')}</ol>${state.comment?`<h2>老师点评</h2><p>${esc(state.comment)}</p>`:''}`;
}
function home(){return heading('START','用三个句型，写出自己的句子','先读懂每一块，再换语块说一句、写一句。今晚先完成五句起步段落，逐渐扩展到作文要求。')+`<div class="grid3"><div class="stat"><b>3 个</b><span>固定句型</span></div><div class="stat"><b>60 个</b><span>可替换动作语块</span></div><div class="stat"><b>24 题</b><span>翻译 · 排序 · 改错</span></div></div><section class="panel"><span class="tag">2026卷写作主题 · 阅读倡议书</span><h2 style="margin-top:14px">Reading for a Better Life</h2><p>作为英语社团负责人李华，号召同学们多读书、读好书。</p><div class="grid3"><div><h3>① 阅读有什么好处？</h3><p class="en">Reading can help us…</p></div><div><h3>② 怎样更好地阅读？</h3><p class="en">We should…</p></div><div><h3>③ 怎样呼吁大家？</h3><p class="en">Let’s…!</p></div></div><div class="callout">原题要求约80词，开头和结尾已给出。今晚是分步训练：先写“2句好处＋2句方法＋1句呼吁”，不把五句起步段落当成完整作文。</div></section><section class="panel"><h2>今天怎样练？</h2><p class="muted">每个句型都有四个步骤，可以在上方小标签之间切换。</p>${DATA.patterns.map((p,i)=>`<button class="bigbtn" data-act="page" data-id="${p.id}">${i+1}. ${p.name}<span>拆句子 → 替换语块 → 独立练习 → 小结</span></button>`).join('')}<div class="tip">先用“基础5组”，熟悉后再打开全部20组。语块库供选用，不要求一节课全部背完。</div></section>`}
function patternView(){const p=ptn();return heading(p.id.toUpperCase(),p.title,p.name+'　先记住固定骨架，再替换表达内容。')+`<div class="tabs">${[['parts','1 拆句子'],['swap','2 替换语块'],['try','3 独立练习'],['recap','4 小结']].map(([v,t])=>`<button data-act="view" data-id="${v}" class="${state.view===v?'active':''}">${t}</button>`).join('')}</div>`+({parts:partsView,swap:swapView,try:tryView,recap:recapView}[state.view]||partsView)(p)}
function partsView(p){const step=trial[p.id+'-step']||0;return `<section class="panel"><span class="tag">每一块是什么？</span><div class="sentence">${p.roles.map(([t,r,d,c])=>`<span class="chunk ${c}">${esc(t)}<small>${r}</small></span>`).join('')}<span>${p.id==='lets'?'!':'.'}</span></div><div class="scroll"><table class="role-table"><thead><tr><th>句子部分</th><th>是什么</th><th>在这里起什么作用</th></tr></thead><tbody>${p.roles.map(([t,r,d])=>`<tr><td class="en" style="font-size:1rem">${esc(t)}</td><td>${r}</td><td>${d}</td></tr>`).join('')}</tbody></table></div><div class="tip">${p.note}</div>${sentence(p.roles.map(x=>x[0]).join(' ')+(p.id==='lets'?'!':'.'))}</section><section class="panel"><h2>短句怎样增加信息？</h2><span class="tag">第 ${step+1} / 3 步</span><p class="en">${esc(p.steps[step][0])}</p><p class="zh">${p.steps[step][1]}</p><div class="actions"><button data-act="grow" data-step="${step-1}" ${step===0?'disabled':''}>上一步</button><button data-act="grow" data-step="${step+1}" ${step===2?'disabled':''}>增加内容 →</button>${sentence(p.steps[step][0])}</div>${p.id==='should'?'<p class="tip">for twenty minutes：持续多久？every day：多久一次？先把 read 写对，再增加时间信息。</p>':''}${p.id==='lets'?'<p class="tip">Let’s enjoy reading! 中，enjoy 紧跟 Let’s，用原形；reading 跟在 enjoy 后，属于 enjoy doing。不是整句话里每个动词都用原形。</p>':''}</section><button class="primary" data-act="view" data-id="swap">开始换语块 →</button>`}
function swapView(p){const m=model(p),list=p.bank.map((b,i)=>({...b,i})).filter(b=>state.all||p.core.includes(b.i));return `<section class="panel"><span class="tag">固定骨架</span><p class="en">${p.id==='can'?'主语 + <b>can help us</b> + 动作语块.':p.id==='should'?'We + <b>should</b> + 动作语块.':'<b>Let’s</b> + 动作语块!'}</p>${p.id==='can'?`<h3>① 选主语：什么活动？</h3><div class="pills">${DATA.subjects.map(([en,zh],i)=>`<button class="small ${state.subject===i?'active':''}" data-act="subject" data-index="${i}">${en}<span class="zh"> · ${zh}</span></button>`).join('')}</div>`:''}<h3>${p.id==='can'?'②':'①'} 选动作语块</h3><div class="pills"><button class="small ${!state.all?'active':''}" data-act="bank-size" data-value="core">基础5组</button><button class="small ${state.all?'active':''}" data-act="bank-size" data-value="all">全部20组</button><span class="count">一次替换一整块，先想意思是否合理。</span></div><div class="builder-result"><span class="tag">我组成的句子</span><p class="en">${state.hideSentence?'先自己说一遍，再展开核对。':esc(m.en)}</p><p class="zh">${m.zh}</p><div class="actions"><button class="small" data-act="hide-sentence">${state.hideSentence?'展开英文':'遮住英文'}</button>${sentence(m.en)}<button class="small primary" data-act="save-sentence">保存我的句子</button></div></div><div class="bank">${list.map(b=>`<button data-act="choose" data-index="${b.i}" class="${state.choices[p.id]===b.i?'active':''}" aria-pressed="${state.choices[p.id]===b.i}"><span class="en">${esc(b.en)}${p.core.includes(b.i)?'<small class="core">基础</small>':''}</span><span class="zh">${b.zh}</span></button>`).join('')}</div><p class="muted">先换最后的动作语块；熟悉后再换主语。保存表示已选入自己的句子本，不代表已经独立掌握。</p></section><button class="primary" data-act="view" data-id="try">遮住例句，自己练 →</button>`}
function exerciseList(){return DATA.exercises.filter(e=>e.pattern===state.pattern)}
function tryView(p){const list=exerciseList(),idx=trial[p.id+'-exercise']||0,q=list[idx],s=recordFor(q);let form='';if(q.type==='order'){if(!trial[q.id])trial[q.id]={pool:q.chunks.map((t,i)=>({t,i})).reverse(),picked:Array.isArray(s.picked)?[...s.picked]:[]};const t=trial[q.id];form=`<p class="muted">点击语块组成句子；点已选语块可撤回。标点已在参考句中提供。</p><div class="answerzone">${t.picked.length?t.picked.map(i=>`<button data-act="unpick" data-index="${i}" ${s.checked?'disabled':''}>${esc(q.chunks[i])}</button>`).join(''):'<span class="muted">把句子放在这里……</span>'}</div><div class="pool">${t.pool.filter(x=>!t.picked.includes(x.i)).map(x=>`<button data-act="pick" data-index="${x.i}" ${s.checked?'disabled':''}>${esc(x.t)}</button>`).join('')}</div>`}else form=`<label class="muted" for="exercise-answer">${q.type==='fix'?'把整句重新写正确':'写一个完整的英文句子'}</label><textarea id="exercise-answer" lang="en" placeholder="在这里写英文……" ${s.checked?'disabled':''}>${esc(s.text)}</textarea>`;
return `<section class="panel"><span class="tag">${{translate:'根据中文写句子',fix:'找错并改正',order:'词块排序'}[q.type]}</span><span class="step">第 ${idx+1} / ${list.length} 题</span><p class="question ${q.type==='fix'?'en':''}">${esc(q.prompt)}</p>${form}<div class="actions"><button class="primary" data-act="check" ${s.checked?'disabled':''}>核对表达</button><button data-act="retry">重新作答</button><button data-act="exercise" data-index="${idx+1}" ${idx===list.length-1?'disabled':''}>下一题 →</button></div>${s.checked?`<div class="feedback ${s.correct?'':'check'}" role="status"><strong>${s.correct?'与参考表达核对通过':'与参考表达不同，请一起核对'}</strong><p class="en">${esc(q.model)}</p><p>${q.why}</p>${!s.correct&&q.type!=='order'?'<p>这是参考表达核对，不是完整语法评分。其他合理表达可由老师确认。</p><button class="small" data-act="accept">老师确认：表达正确</button>':''}</div>`:state.teacher?`<details><summary>教师参考表达</summary><p class="en">${esc(q.model)}</p><p>${q.why}</p></details>`:''}<div class="jump">${list.map((e,i)=>`<button data-act="exercise" data-index="${i}" class="${i===idx?'active':''} ${state.exercises[e.id]?.checked?(state.exercises[e.id].correct?'done':'wrong'):''}">${i+1}</button>`).join('')}</div><p class="count">自动核对忽略大小写与标点；排序题按语块顺序核对。</p></section>`}
function recapView(p){return `<section class="panel"><h2>不用看例句，说一说</h2><ol><li>这个句型用来表达什么？</li><li>固定不动的部分是哪一块？</li><li>后面的第一个动词应该是什么形式？</li><li>换一个内容，你还能自己说一句吗？</li></ol><div class="tip">${p.note}</div><div class="actions"><button data-act="view" data-id="swap">回到语块库</button><button class="primary" data-act="page" data-id="${p.id==='can'?'should':p.id==='should'?'lets':'write'}">${p.id==='lets'?'自己写五句话':'学习下一个句型'} →</button></div></section>`}
const draftLabels=['阅读的好处①','阅读的好处②','阅读的方法①','阅读的方法②','呼吁大家行动'];const draftHints=['Reading can help us…','Reading books can help us…','We should…','We should…','Let’s…!'];
function writeView(){const count=state.drafts.join(' ').trim().match(/[A-Za-z]+(?:['’][A-Za-z]+)*/g)?.length||0;return heading('WRITE','把自己的五句话连起来','先完成两个好处、两条方法和一句呼吁。可以借助句型开头，逐渐减少提示。')+`<section class="panel"><div class="actions"><span class="tag">五句起步段落</span><button class="small" data-act="draft-hints">${trial.hideHints?'显示句型开头':'遮住句型开头'}</button><button class="small" data-act="draft-check">检查写作清单</button></div>${draftLabels.map((label,i)=>`<div class="draft-row"><label for="draft-${i}">${i+1}. ${label}</label>${trial.hideHints?'':`<div class="hint">${draftHints[i]}</div>`}<textarea id="draft-${i}" data-draft="${i}" lang="en" placeholder="写你自己的句子……">${esc(state.drafts[i])}</textarea></div>`).join('')}<p class="count" id="draft-count">${state.drafts.filter(x=>x.trim()).length} / 5 句已填写 · 约 ${count} 个英文词</p>${trial.draftCheck?`<div class="feedback check"><h3>自己检查，再请老师确认</h3><ul class="review-list">${draftChecks().map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>清单只提示常见形式，不代替老师检查语义、拼写和完整语法。</p></div>`:''}<div class="actions"><button class="primary" data-act="read-draft">▷ 朗读我的段落</button><button data-act="export-text">导出我的句子</button><button data-act="print">打印学习单</button></div><div class="callout">原题约80词；这五句话只是今天的起步练习。先写完整、写正确，之后再增加细节。</div></section><details ${state.teacher?'open':''}><summary>老师点评与参考小段落</summary><label class="muted" for="comment">老师点评（自动保存）</label><textarea id="comment" placeholder="记录需要改进的表达……">${esc(state.comment)}</textarea><details><summary>展开参考小段落</summary><p class="en">Reading can help us learn new things.<br>Reading books can help us relax.<br>We should read for twenty minutes every day.<br>We should share good books with friends.<br>Let’s enjoy reading!</p><p class="muted">参考段落不计入学生完成情况。</p></details></details>`}
function draftChecks(){const notes=[];const filled=state.drafts.filter(x=>x.trim()).length;notes.push(`内容填写：${filled}/5。目标是两个好处、两条方法、一个呼吁。`);state.drafts.forEach((text,i)=>{if(!text.trim())return;const n=norm(text);if(/\bcan helps\b/.test(n))notes.push(`第${i+1}句：can 后的 helps 应检查是否需要改成 help。`);if(/\bshould (to|reading|choosing|takes)\b/.test(n))notes.push(`第${i+1}句：should 后检查动词原形，不加 to。`);if(/\blet's (to|reads)\b/.test(n))notes.push(`第${i+1}句：Let’s 后检查动词原形。`);if(/\benjoy read\b/.test(n))notes.push(`第${i+1}句：enjoy 后的 read 应检查是否改成 reading。`)});notes.push('逐句问自己：说的是谁？做什么？意思合理吗？首字母和句末标点写好了吗？');return notes}
function savedView(){const completed=Object.values(state.exercises).filter(x=>x.checked),wrong=DATA.exercises.filter(q=>state.exercises[q.id]?.checked&&!state.exercises[q.id].correct);return heading('MY WORK','自己的句子与练习记录','句子、练习和草稿自动保存在当前浏览器。换设备前，可以导出记录备份。')+`<div class="grid3"><div class="stat"><b>${state.saved.length}</b><span>保存的替换句</span></div><div class="stat"><b>${completed.length} / 24</b><span>已核对练习</span></div><div class="stat"><b>${wrong.length}</b><span>待一起核对</span></div></div><section class="panel"><h2>我的替换句</h2><div class="savedlist">${state.saved.length?state.saved.map((s,i)=>`<div class="saveditem"><div><div class="en">${esc(s.en)}</div><p class="zh">${esc(s.zh)}</p></div>${sentence(s.en)}<button class="small" data-act="remove-saved" data-index="${i}" aria-label="移除第${i+1}句">×</button></div>`).join(''):'<p class="empty">在“替换语块”中组句，再点击“保存我的句子”。</p>'}</div></section>${wrong.length?`<section class="panel"><h2>再练一次</h2>${wrong.map(q=>`<button class="bigbtn" data-act="open-error" data-id="${q.id}">${esc(q.prompt)}<span>回到练习 →</span></button>`).join('')}</section>`:''}<div class="actions"><button data-act="export-text">导出我的句子</button><button data-act="backup">导出全部记录</button><button data-act="import">导入记录</button><button data-act="print">打印学习单</button></div><p class="muted">导入会合并保存的句子，并用导入文件中的同名练习与草稿替换当前内容。</p>`}
function norm(text){return String(text).toLowerCase().replace(/[‘’]/g,"'").replace(/[^a-z0-9' ]/g,' ').replace(/\s+/g,' ').trim()}
function currentQ(){return exerciseList()[trial[state.pattern+'-exercise']||0]}
function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function initVoices(){voiceList='speechSynthesis'in window?speechSynthesis.getVoices().filter(v=>/^en[-_]/i.test(v.lang)):[];const el=$('#voice');el.innerHTML=voiceList.length?voiceList.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} (${v.lang})</option>`).join(''):'<option value="">暂无英语语音</option>';const selected=voiceList.find(v=>v.voiceURI===state.voices)||voiceList.find(v=>v.lang==='en-GB')||voiceList[0];if(selected){state.voices=selected.voiceURI;el.value=selected.voiceURI}$('#voice-note').textContent=voiceList.length?'朗读使用设备英语语音，也可由老师示范。':'此设备暂未提供英语语音，请由老师示范；文字练习可以照常使用。'}
function speak(text){if(!voiceList.length){toast('暂无英语语音，可由老师朗读。');return}stop();const u=new SpeechSynthesisUtterance(text);u.voice=voiceList.find(v=>v.voiceURI===state.voices)||voiceList[0];u.lang=u.voice.lang;u.rate=.82;u.onerror=()=>toast('朗读未能播放，请重试或由老师示范。');speechSynthesis.speak(u)}
document.addEventListener('input',event=>{const el=event.target;if(el.id==='exercise-answer'){recordFor(currentQ()).text=el.value;save()}if(el.dataset.draft!==undefined){state.drafts[Number(el.dataset.draft)]=el.value;save();const n=state.drafts.join(' ').match(/[A-Za-z]+(?:['’][A-Za-z]+)*/g)?.length||0;$('#draft-count').textContent=`${state.drafts.filter(x=>x.trim()).length} / 5 句已填写 · 约 ${n} 个英文词`}if(el.id==='comment'){state.comment=el.value;save()}});
document.addEventListener('change',e=>{if(e.target.id==='voice'){state.voices=e.target.value;save()}if(e.target.id==='import-file')importData(e.target.files[0])});
document.addEventListener('click',event=>{const b=event.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act,i=Number(b.dataset.index);
 if(a==='page'){go(b.dataset.id);return}if(a==='speak'){speak(b.dataset.text);return}if(a==='teacher'){state.teacher=!state.teacher;save();render();return}if(a==='font'){state.font=state.font===19?22:state.font===22?25:19;save();render();return}if(a==='hide-zh'){state.hideZh=!state.hideZh;save();render();return}if(a==='view'){state.view=b.dataset.id;stop();save();render();return}
 if(a==='grow')trial[state.pattern+'-step']=Math.max(0,Math.min(2,Number(b.dataset.step)));
 if(a==='subject')state.subject=i;if(a==='choose')state.choices[state.pattern]=i;if(a==='bank-size')state.all=b.dataset.value==='all';if(a==='hide-sentence')state.hideSentence=!state.hideSentence;
 if(a==='save-sentence'){const m=model();if(state.saved.some(s=>s.en===m.en)){toast('这句话已经保存。');return}state.saved.push({...m,pattern:state.pattern});toast('已保存到我的句子。')}
 if(a==='exercise'){trial[state.pattern+'-exercise']=i}
 if(a==='pick'||a==='unpick'){const q=currentQ(),t=trial[q.id];if(a==='pick'&&!t.picked.includes(i))t.picked.push(i);if(a==='unpick')t.picked=t.picked.filter(x=>x!==i)}
 if(a==='retry'){const q=currentQ();state.exercises[q.id]={text:'',checked:false};delete trial[q.id]}
 if(a==='check'){const q=currentQ(),s=recordFor(q);if(q.type==='order'){const t=trial[q.id];if(t.picked.length!==q.chunks.length)return toast('先把所有语块放入句子。');s.text=t.picked.map(i=>q.chunks[i]).join(' ');s.picked=[...t.picked]}if(!s.text.trim())return toast('先写一个完整句子。');s.checked=true;s.correct=q.accepted.some(x=>norm(x)===norm(s.text))}
 if(a==='accept')recordFor(currentQ()).correct=true;
 if(a==='draft-hints')trial.hideHints=!trial.hideHints;if(a==='draft-check')trial.draftCheck=true;
 if(a==='read-draft'){const text=state.drafts.filter(x=>x.trim()).join(' ');if(!text)return toast('先写一句话。');speak(text);return}
 if(a==='remove-saved')state.saved.splice(i,1);
 if(a==='open-error'){const q=DATA.exercises.find(q=>q.id===b.dataset.id);state.page=q.pattern;state.pattern=q.pattern;state.view='try';trial[q.pattern+'-exercise']=exerciseList().findIndex(x=>x.id===q.id);state.exercises[q.id]={text:'',checked:false};delete trial[q.id]}
 if(a==='export-text'){download('简单句写作_我的句子.txt',['我的五句话',...state.drafts,'','我保存的句子',...state.saved.map(x=>x.en),'','老师点评',state.comment].join('\n'));return}
 if(a==='backup'){download('简单句写作_学习记录.json',JSON.stringify({app:KEY,version:1,state},null,2),'application/json');return}
 if(a==='import'){$('#import-file').click();return}
 if(a==='print'){render();window.print();return}
 save();render();
});
async function importData(file){if(!file)return;try{if(file.size>2e6)throw Error('文件太大');const d=JSON.parse(await file.text());if(d.app!==KEY||d.version!==1||!d.state)throw Error('不是本模块导出的文件');const s=d.state;if(!Array.isArray(s.saved)||!Array.isArray(s.drafts)||s.drafts.length!==5||s.drafts.some(x=>typeof x!=='string'))throw Error('记录结构不正确');for(const x of s.saved)if(x&&typeof x.en==='string'&&typeof x.zh==='string'&&!state.saved.some(y=>y.en===x.en))state.saved.push({en:x.en.slice(0,2000),zh:x.zh.slice(0,2000),pattern:x.pattern});for(const q of DATA.exercises){const r=s.exercises?.[q.id];if(r&&typeof r.text==='string')state.exercises[q.id]={text:r.text.slice(0,3000),checked:!!r.checked,correct:!!r.correct,...(q.type==='order'&&Array.isArray(r.picked)&&r.picked.every(i=>Number.isInteger(i)&&i>=0&&i<q.chunks.length)?{picked:[...new Set(r.picked)]}:{})}}state.drafts=s.drafts.map(x=>x.slice(0,5000));state.comment=typeof s.comment==='string'?s.comment.slice(0,5000):state.comment;save();render();toast('记录已导入。')}catch(e){toast('导入失败：'+e.message)}finally{$('#import-file').value=''}}
if(!['home','can','should','lets','write','saved'].includes(state.page))state.page='home';if(!['parts','swap','try','recap'].includes(state.view))state.view='parts';if(![19,22,25].includes(state.font))state.font=19;
render();initVoices();if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',initVoices);
